head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07450";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07450.onpageload' });
    }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_openStkcertIsuStatDtlWin();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        fn_print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07450.btn_print_onclick' }); }
};

/**
 * @method
 * @name grd_stkcertIsu_oncellclick
 * @description grd_stkcertIsu 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_stkcertIsu_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_stkcertIsu');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_stkcertIsu */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.openStkcertIsuStatDtlWin(r["bzProcsNo"], r["stkcertIsuSeq"], r["listDdOri"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_stkcertIsu.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_openStkcertIsuStatDtlWin
 * @description open Stkcert Isu Stat Dtl Win 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openStkcertIsuStatDtlWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openStkcertIsuStatDtlWin",
        method: "post",
        action: "/konex/ListPrelmInvstgKonex.do",
        ref: "dma_openStkcertIsuStatDtlWinReq",
        target: "dlt_stkcertIsu=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openStkcertIsuStatDtlWin
 * @description open Stkcert Isu Stat Dtl Win 처리
 * @param {*} bzprocsno bzprocsno
 * @param {*} stkcertIsuSeq stkcertIsuSeq
 * @param {String} listDd listDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStkcertIsuStatDtlWin = async function (bzprocsno, stkcertIsuSeq, listDd) {
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('stkcertIsuSeq', stkcertIsuSeq);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('bzProcsNoSearch', bzprocsno);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('listDd', listDd);
    $c.util.getComponent('dma_openStkcertIsuStatDtlWinReq').set('nowPage', '61');
    await scwin.tx_fn_openStkcertIsuStatDtlWin();
};
